package com.powerliq.marketdata;
import com.powerliq.api.contracts.ServiceException;import com.powerliq.events.*;
import java.sql.*;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class MarketDataService{
 private final JdbcTemplate jdbc;public MarketDataService(JdbcTemplate jdbc){this.jdbc=jdbc;}
 @Transactional public boolean consume(EventEnvelope<MarketPriceRevisionV1> event){
  if(!"market-price.revised".equals(event.eventType())||event.eventVersion()!=1)throw new ServiceException(MarketDataErrorCode.EVENT_TYPE_UNSUPPORTED,"Only market-price.revised v1 is supported");
  var p=event.payload();if(!p.deliveryStart().isBefore(p.deliveryEnd()))throw new ServiceException(MarketDataErrorCode.EVENT_INVALID,"Delivery interval is invalid");
  int inserted=jdbc.update("INSERT INTO market_price_revisions(event_id,provider,delivery_start,delivery_end,price_gbp_mwh,source_revision,source_timestamp,retrieved_at,correlation_id) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(event_id) DO NOTHING",event.eventId(),p.provider(),ts(p.deliveryStart()),ts(p.deliveryEnd()),p.priceGbpPerMWh(),p.sourceRevision(),ts(p.sourceTimestamp()),ts(p.retrievedAt()),event.correlationId());
  if(inserted==0)return false;
  jdbc.update("INSERT INTO current_market_prices(provider,delivery_start,event_id,delivery_end,price_gbp_mwh,source_revision,source_timestamp,retrieved_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(provider,delivery_start) DO UPDATE SET event_id=EXCLUDED.event_id,delivery_end=EXCLUDED.delivery_end,price_gbp_mwh=EXCLUDED.price_gbp_mwh,source_revision=EXCLUDED.source_revision,source_timestamp=EXCLUDED.source_timestamp,retrieved_at=EXCLUDED.retrieved_at WHERE (EXCLUDED.source_timestamp,EXCLUDED.retrieved_at,EXCLUDED.event_id)>(current_market_prices.source_timestamp,current_market_prices.retrieved_at,current_market_prices.event_id)",p.provider(),ts(p.deliveryStart()),event.eventId(),ts(p.deliveryEnd()),p.priceGbpPerMWh(),p.sourceRevision(),ts(p.sourceTimestamp()),ts(p.retrievedAt()));return true;
 }
 @Transactional(readOnly=true) public MarketPrice latest(String provider,Instant start){return jdbc.query("SELECT * FROM current_market_prices WHERE provider=? AND delivery_start=?",this::map,provider,ts(start)).stream().findFirst().orElseThrow(()->new ServiceException(MarketDataErrorCode.MARKET_PRICE_NOT_FOUND,"Market price was not found"));}
 @Transactional(readOnly=true) public List<MarketPrice> history(String provider,Instant from,Instant to,int limit){if(from==null||to==null||!from.isBefore(to)||Duration.between(from,to).compareTo(Duration.ofDays(31))>0||limit<1||limit>1000)throw new ServiceException(MarketDataErrorCode.MARKET_DATA_INVALID_RANGE,"Range must be ordered, at most 31 days, and limit 1 to 1000");return jdbc.query("SELECT * FROM market_price_revisions WHERE provider=? AND delivery_start>=? AND delivery_start<? ORDER BY delivery_start,source_timestamp,retrieved_at,event_id LIMIT ?",this::map,provider,ts(from),ts(to),limit);}
 private MarketPrice map(ResultSet r,int n)throws SQLException{return new MarketPrice(r.getObject("event_id",UUID.class),r.getString("provider"),r.getTimestamp("delivery_start").toInstant(),r.getTimestamp("delivery_end").toInstant(),r.getBigDecimal("price_gbp_mwh"),r.getString("source_revision"),r.getTimestamp("source_timestamp").toInstant(),r.getTimestamp("retrieved_at").toInstant());}private Timestamp ts(Instant i){return Timestamp.from(i);}
}
